#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^# room.date.start' "$t" || { echo "header line lost"; fail=1; }
grep -q '^kaede.2026-01-05.13:00' "$t" || { echo "other booking lost"; fail=1; }
err=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >"$t.out"); rc=$?
[ $rc = 1 ] && [ ! -s "$t.out" ] && [ "$err" = 'not found: aoi 2026-01-05 11:00' ] || { echo "not found: exit/stdout/stderr wrong"; fail=1; }
err=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>&1 >"$t.out"); rc=$?
[ $rc = 2 ] && [ ! -s "$t.out" ] && [ "$err" = 'usage: cancel.sh ROOM DATE START' ] || { echo "usage: exit/stdout/stderr wrong"; fail=1; }
t2=$(mktemp); printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t09:00\t10:00\tz\n' > "$t2"
BOOKINGS=$t2 bash src/cancel.sh aoi 2026-01-05 09:00 >/dev/null 2>&1; [ $? = 1 ] && grep -q '^kaede.2026-01-05.09:00' "$t2" || { echo "other room's booking removed"; fail=1; }
rm -f "$t" "$t.out" "$t2"; exit $fail

