#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\n' > "$t"
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 09:00 10:30 x >/dev/null || { echo "book failed"; fail=1; }
grep -q '^# room' "$t" && grep -q '^aoi.2026-01-05.09:00.10:30.x$' "$t" || { echo "booking not appended"; fail=1; }
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 10:00 11:00 y >/dev/null 2>&1; [ $? = 1 ] || { echo "overlap should exit 1"; fail=1; }
rm -f "$t"; exit $fail

spec/cancel.spec.sh.text:
#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
# the header and the other booking stay as they were
printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t.want"
cmp -s "$t" "$t.want" || { echo "file changed beyond the cancelled row"; fail=1; }
# not found: exit 1, message on stderr, nothing on stdout
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); rc=$?
[ $rc = 1 ] || { echo "not found should exit 1 (got $rc)"; fail=1; }
[ -z "$out" ] || { echo "not found should print nothing on stdout: $out"; fail=1; }
err=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null)
[ "$err" = 'not found: aoi 2026-01-05 11:00' ] || { echo "not found message on stderr: $err"; fail=1; }
# wrong argument count: exit 2, usage on stderr, nothing on stdout
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2>/dev/null); rc=$?
[ $rc = 2 ] || { echo "usage should exit 2 (got $rc)"; fail=1; }
[ -z "$out" ] || { echo "usage should not print on stdout: $out"; fail=1; }
err=$(BOOKINGS=$t bash src/cancel.sh aoi 2>&1 >/dev/null)
[ "$err" = 'usage: cancel.sh ROOM DATE START' ] || { echo "usage text on stderr: $err"; fail=1; }
# same date and start in another room must not be cancelled
t2=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t10:00\ty\n' > "$t2"
BOOKINGS=$t2 bash src/cancel.sh aoi 2026-01-05 09:00 >/dev/null || { echo "cancel in same-slot case failed"; fail=1; }
printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t09:00\t10:00\ty\n' > "$t2.want"
cmp -s "$t2" "$t2.want" || { echo "other room's booking was removed"; fail=1; }
rm -f "$t" "$t.want" "$t2" "$t2.want"; exit $fail

