#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\n' > "$t"
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 09:00 10:30 x >/dev/null || { echo "book failed"; fail=1; }
grep -q '^# room' "$t" && grep -q '^aoi.2026-01-05.09:00.10:30.x$' "$t" || { echo "booking not appended"; fail=1; }
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 10:00 11:00 y >/dev/null 2>&1; [ $? = 1 ] || { echo "overlap should exit 1"; fail=1; }
rm -f "$t"; exit $fail

spec/cancel.spec.sh.text:
#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^# room' "$t" || { echo "header line removed"; fail=1; }
grep -q '^kaede.2026-01-05.13:00' "$t" || { echo "other booking removed"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 >/dev/null 2>&1; [ $? = 1 ] || { echo "not found should exit 1"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 >/dev/null 2>&1; [ $? = 2 ] || { echo "usage should exit 2"; fail=1; }
t2=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t10:00\ty\n' > "$t2"
BOOKINGS=$t2 bash src/cancel.sh aoi 2026-01-05 09:00 >/dev/null || { echo "cancel failed (same slot, other room)"; fail=1; }
grep -q '^kaede.2026-01-05.09:00' "$t2" || { echo "other room same slot removed"; fail=1; }
rm -f "$t" "$t2"; exit $fail

