#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^# room' "$t" || { echo "header line lost"; fail=1; }
grep -q '^kaede.2026-01-05.13:00' "$t" || { echo "other booking lost"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 >"$t.out" 2>"$t.err"; rc=$?
[ $rc = 1 ] || { echo "not found should exit 1, got $rc"; fail=1; }
[ ! -s "$t.out" ] || { echo "not found should not print to stdout"; fail=1; }
grep -q '^not found: aoi 2026-01-05 11:00$' "$t.err" || { echo "not found should print to stderr"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 >"$t.out" 2>"$t.err"; rc=$?
[ $rc = 2 ] || { echo "usage should exit 2, got $rc"; fail=1; }
[ ! -s "$t.out" ] || { echo "usage should not print to stdout"; fail=1; }
grep -q '^usage: cancel.sh ROOM DATE START$' "$t.err" || { echo "usage should print to stderr"; fail=1; }
rm -f "$t.out" "$t.err"
t2=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t10:00\ty\n' > "$t2"
out=$(BOOKINGS=$t2 bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel of aoi failed"; fail=1; }
grep -q '^kaede.2026-01-05.09:00' "$t2" || { echo "another room's booking at the same date and start was removed"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t2" || { echo "aoi booking still there"; fail=1; }
rm -f "$t" "$t2"; exit $fail

