#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^# room' "$t" && grep -q '^kaede.2026-01-05.13:00' "$t" || { echo "header or other booking removed"; fail=1; }
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); [ $? = 1 ] || { echo "not found should exit 1"; fail=1; }
[ -z "$out" ] || { echo "not found should print nothing to stdout: $out"; fail=1; }
err=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null); [ "$err" = 'not found: aoi 2026-01-05 11:00' ] || { echo "not found message on stderr: $err"; fail=1; }
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>/dev/null); [ $? = 2 ] || { echo "usage should exit 2"; fail=1; }
[ -z "$out" ] || { echo "usage should print nothing to stdout: $out"; fail=1; }
err=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>&1 >/dev/null); [ "$err" = 'usage: cancel.sh ROOM DATE START' ] || { echo "usage message on stderr: $err"; fail=1; }
r=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t10:00\ty\n' > "$r"
BOOKINGS=$r bash src/cancel.sh aoi 2026-01-05 09:00 >/dev/null || { echo "cancel aoi failed"; fail=1; }
grep -q '^kaede.2026-01-05.09:00' "$r" || { echo "other room's booking at the same date and start removed"; fail=1; }
rm -f "$r" "$t"; exit $fail

