#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
[ "$(head -1 "$t")" = "$(printf '# room\tdate\tstart\tend\twho')" ] || { echo "header line changed"; fail=1; }
[ "$(grep -c '^kaede' "$t")" = 1 ] || { echo "other booking (kaede) changed"; fail=1; }
o=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); c=$?
[ "$c" = 1 ] || { echo "not found should exit 1"; fail=1; }
[ -z "$o" ] || { echo "not found should print nothing to stdout: $o"; fail=1; }
o=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>/dev/null); c=$?
[ "$c" = 2 ] || { echo "usage should exit 2"; fail=1; }
[ -z "$o" ] || { echo "usage should print nothing to stdout: $o"; fail=1; }
e=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>&1 >/dev/null)
[ "$e" = 'usage: cancel.sh ROOM DATE START' ] || { echo "usage text on stderr: $e"; fail=1; }
rm -f "$t"

t=$(mktemp); printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t09:00\t10:00\ty\naoi\t2026-01-05\t09:00\t10:00\tx\n' > "$t"
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00 >/dev/null || { echo "cancel of aoi failed"; fail=1; }
grep -q '^kaede.2026-01-05.09:00' "$t" || { echo "same date and start in another room was removed"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "aoi booking still there"; fail=1; }
rm -f "$t"; exit $fail

